# A minimal microservice: one responsibility, one HTTP interface
from fastapi import FastAPI

app = FastAPI()

# This service owns ONLY inventory logic
@app.get("/inventory/{sku}")
async def get_stock(sku: str):
    stock = await db.query("SELECT qty FROM inventory WHERE sku = $1", sku)
    return {"sku": sku, "available": stock["qty"]}

@app.post("/inventory/{sku}/reserve")
async def reserve(sku: str, qty: int):
    # Only this service writes to the inventory table
    await db.execute("UPDATE inventory SET qty = qty - $1 WHERE sku = $2", qty, sku)
    return {"reserved": qty}

