from fastapi import FastAPI

app = FastAPI()

# Strategy 1: URI path versioning
@app.get("/v1/orders/{order_id}")
async def get_order_v1(order_id: str):
    # Old schema: shipping address embedded in order object
    return {"orderId": order_id, "address": {...}}

@app.get("/v2/orders/{order_id}")
async def get_order_v2(order_id: str):
    # New schema: address as a separate linked resource
    return {
        "orderId": order_id,
        "addressLink": f"/v2/addresses/{order_id}-shipping"
    }

