-- The shared database anti-pattern that creates a distributed monolith
-- Multiple services all query the SAME orders table directly

-- From order-service (writes and reads)
SELECT * FROM orders WHERE customer_id = $1;

-- From fulfillment-service (reads directly — bypasses order-service API!)
SELECT id, shipping_address FROM orders WHERE status = 'confirmed';

-- From analytics-service (reads directly — bypassed order-service API!)
SELECT DATE(created_at), COUNT(*) FROM orders GROUP BY 1;

-- Now any schema change to orders breaks ALL THREE services
-- They cannot deploy independently — distributed monolith
